head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gUsrId = js_id; // 세션 사용자ID
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gAllChk = false;
scwin.gTrnsType = 'S'; // N: 쪽지, S: 문자 , M: 이메일, F:팩스


// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

scwin.vScrenID = "ULDSTF30308.xml";
scwin.gNOTI_SVC_ID;
scwin.gAddInput;
scwin.marketNm;X < !내부사용자--;
기본정보;
읽어오기-- > function() {
    var url = "/NoteMgt.do?method=getInnerUserInfo&inputMessageId=NOTI_INOUT" + "&outputMessageId=NOTI_INOUT" + "&USR_ID=" + scwin.gUsrId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_usr_basic.DataID = encodeURI(url);
    dts_usr_basic.reset();
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    //gNOTI_SVC_ID = dts_Grid.NameString(row, "NOTI_SVC_ID");
    var url = "/SmsMgt.do?method=readSendSMSInfo" + "&inputMessageId=SMS_INFO_INOUT" + "&outputMessageId=SMS_INFO_INOUT" + "&NOTI_SVC_ID=" + scwin.gNOTI_SVC_ID + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    dts_Master.DataID = encodeURI(url);
    dts_Master.Reset();
    var urlReceiver = "/NoteMgt.do?method=listSendSMSReceiver" + "&inputMessageId=BIZSPT_EMAIL_SMS_RECEIVER_INOUT" + "&NOTI_SVC_ID=" + scwin.gNOTI_SVC_ID + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Receiver.DataID = encodeURI(urlReceiver);
    dts_Receiver.Reset();
};
scwin.fn_SetHeader = function() {
    dts_Master.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_EMAIL_SMS_RECEIVER_INOUT";
    dts_Master.Reset();
    dts_Master.insertRow();
    dts_Receiver.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MAIL_RECEIPTPLACE_OUT";
    dts_Receiver.Reset();
};
scwin.fn_SetCode = function() {
    $c.stf.setObjectValue(txb_EMP_NO, scwin.gEmpNo);
    $c.stf.setObjectValue(txb_dep_cd, scwin.gDepCd);
    $c.stf.setObjectValue(txb_fromName, js_emp_nm);
    $c.stf.setObjectValue(txb_fromEmail, js_email);
    $c.stf.setObjectValue(cmb_EMAIL, "N");
    $c.stf.setObjectValue(cmb_Reserve, "N");
    $c.stf.setObjectValue(txb_msg_gbn, $c.stf.getQuery(frame.srcUrl, "MSG_GBN"));
};
scwin.initPage = function() {
    scwin.gNOTI_SVC_ID = $c.stf.getQuery(frame.srcUrl, "NOTI_SVC_ID");
    scwin.gAddInput = $c.stf.getQuery(frame.srcUrl, "ADD_INPUT");
    if (scwin.gAddInput == 'Y') {
        scwin.fn_read();
        scwin.fn_SetCode();
    } else {
        scwin.fn_SetHeader();
        scwin.fn_SetCode();
    }
    fn_ReadBasicInfo();
    if ($c.stf.getObjectValue(txb_msg_gbn) == '2') {
        //(유)주식시장운영팀, 코스닥시장운영팀, 코넥스시장운영팀
        if (scwin.gDepCd == "2220" || scwin.gDepCd == "3220" || scwin.gDepCd == "3B10") {
            if (scwin.gDepCd == "2220") {
                $c.stf.setObjectValue(txa_title, "자사주호가 미제출하신분은 장종료 30분전까지 제출바랍니다. 유가 운영팀");
            } else if (scwin.gDepCd == "3220") {
                scwin.marketNm = "KOSDAQ";
                $c.stf.setObjectValue(txa_title, "자사주 호가제출 마감 10분 전입니다.\n" + "- " + scwin.marketNm + " 시장운영팀 -");
            } else if (scwin.gDepCd == "3B10") {
                scwin.marketNm = "KONEX";
                $c.stf.setObjectValue(txa_title, "자사주 호가제출 마감 20분 전입니다.\n" + "- " + scwin.marketNm + " 시장운영팀 -");
            }
        }
        $c.cm.setColumnProp(grd_Receiver, "COM_ABBRV", "Show", false);
        $c.cm.setColumnProp(grd_Receiver, "EMAIL", "name", '신청일자');
        $c.cm.setColumnProp(grd_Receiver, "EMAIL", "mask", 'XXXX-XX-XX');
        $c.cm.setColumnProp(grd_Receiver, "CHRG_NM", "width", '200');
        $c.cm.setColumnProp(grd_Receiver, "CELLPHONE_NO", "width", '260');
        cmb_EMAIL.setDisabled(true);
    }
};
scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(panel_debug, false);
    $c.stf.showObj(txb_msg_gbn, false);
};
scwin.fn_registerSMS = function() {
    if (scwin.fn_CheckForm()) {
        var msg = $c.stf.getMessageParam("MSG-A006", "전송");
        var res = window.confirm(msg);
        if (res) {
            dts_Master.setCellData(1, "EMAIL_YN", $c.stf.getObjectValue(cmb_EMAIL));
            dts_Master.setCellData(1, "RESERVE_YN", $c.stf.getObjectValue(cmb_Reserve));
            dts_Master.setCellData(1, "RESERVE_DATE", $c.stf.getObjectValue(edt_Reserve_Date));
            dts_Master.setCellData(1, "RESERVE_HH", $c.stf.getObjectValue(cmb_Reserve_hh));
            dts_Master.setCellData(1, "RESERVE_MM", $c.stf.getObjectValue(cmb_Reserve_mm));
            var url = "/SmsMgt.do?method=registerSMS" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master, I:pInputDetail=dts_Receiver)";
            trs_Save.post();
        }
    }
};
scwin.fn_CheckForm = function() {
    var msg = "";
    if ($c.stf.getObjectValue(txa_title) == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "보내는 내용");
        $c.win.alert(msg);
        txa_title.Focus();
        return false;
    }

    //setObjectValue(txb_title_size, getStringSize(getObjectValue(txa_title)));

    if ($c.stf.getStringSize($c.stf.getObjectValue(txa_title)) > 80) {
        $c.win.alert('보내는내용이 80Byte가 초과되었습니다.');
        txa_title.Focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_snd_no) == "" || $c.stf.getObjectValue(txb_snd_no) == "-") {
        msg = $c.stf.getMessageParam("MSG-A005", "보내는 번호");
        $c.win.alert(msg);
        txb_snd_no.focus();
        return false;
    }
    if (!$c.stockSearch.isNumber($c.stf.getObjectValue(txb_snd_no))) {
        $c.win.alert("[보내는 번호]를 숫자로 입력해주세요.");
        //txb_snd_no.value = "";
        txb_snd_no.focus();
        return;
    }
    if ($c.stf.getStringSize($c.stf.getObjectValue(txb_snd_no)) > 11) {
        $c.win.alert('보내는 번호가 11Byte가 초과되었습니다.');
        txb_snd_no.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_EMP_NO) == "") {
        $c.win.alert("세션정보를 받지 못했습니다.");
        txb_EMP_NO.focus();
        return false;
    }

    // dts_Receiver 에서 CHECK 된 걸 찾는다.
    var total = 0;
    for (var i = 0; i < dts_Receiver.getTotalRow(); i++) {
        var chk = dts_Receiver.getCellData(i, "CHECK");
        if (chk == "T" || chk == "1") {
            total++;
        }
    }
    if (total == 0) {
        $c.win.alert("선택된 수신자가 없습니다.");
        return false;
    }

    // 예약전송 체크
    if ($c.stf.getObjectValue(cmb_Reserve) == 'Y') {
        if ($c.stf.getObjectValue(cmb_Reserve_hh) == "" || $c.stf.getObjectValue(cmb_Reserve_hh) == "99") {
            $c.win.alert("예약 전송일자의 시를 선택하세요.");
            cmb_Reserve_hh.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_Reserve_mm) == "" || $c.stf.getObjectValue(cmb_Reserve_mm) == "99") {
            $c.win.alert("예약 전송일자의 분을 선택하세요.");
            cmb_Reserve_mm.focus();
            return false;
        }
        var dNow = new Date();

        // 현재 날짜,시간
        var pYear = dNow.getYear();
        var pMonth = dNow.getMonth() + 1;
        var pDay = dNow.getDate();
        var pHour = dNow.getHours();
        var pMinute = dNow.getMinutes();
        if (pMonth <= 9) {
            pMonth = "0" + pMonth;
        }
        if (pDay <= 9) {
            pDay = "0" + pDay;
        }
        var pDate = pYear + "" + pMonth + "" + pDay;

        // 예약전송  날짜,시간
        var rYear = $c.stf.getObjectValue(edt_Reserve_Date).substring(0, 4);
        var rMonth = $c.stf.getObjectValue(edt_Reserve_Date).substring(4, 6);
        var rDay = $c.stf.getObjectValue(edt_Reserve_Date).substring(6, 8);
        var rHour = $c.stf.getObjectValue(cmb_Reserve_hh);
        var rMinute = $c.stf.getObjectValue(cmb_Reserve_mm);

        // 현재시간
        var dateA = new Date(pYear, pMonth, pDay, pHour, pMinute);
        // 예약전송 시간
        var dateB = new Date(rYear, rMonth, rDay, rHour, rMinute);
        var mSecond = Math.floor(dateB.getTime() - dateA.getTime()) / 1000;
        var mMinute = Math.floor(mSecond / 60);
        var mHour = Math.floor(mMinute / 60);
        var mDay = Math.floor(mHour / 24);
        var diff_hour = Math.floor(mHour % 24);
        var diff_minute = Math.floor(mMinute % 60);

        //alert ('계산시간 : ' + mDay + '일 ' + diff_hour + ' 시간 ' + diff_minute + ' 분' );

        if (mDay > 0 || diff_hour > 0 || diff_minute >= 10) {
            return true;
        } else {
            $c.win.alert("예약메시지 전송은 현재시간을 기준으로 10분 이후부터 가능합니다.");
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_EMAIL) == 'Y') {
        if (js_svrGubun == 'local' || js_svrGubun == 'dev' || js_svrGubun == 'test') {
            $c.win.alert("◆ 주의 사항 ◆\n\n개발환경에서도 메일이 발송되므로 수신자 메일주소를 확인바랍니다.");
        }
    }
    return true;
};
scwin.fn_Cancel = function() {
    scwin.fn_SetHeader();
    scwin.fn_SetCode();
    fn_ReadBasicInfo();
};
scwin.fn_SelectAll = function() {
    grd_Receiver.Redraw = false;
    if (scwin.gAllChk == false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        for (var i = 0; i < dts_Receiver.getTotalRow(); i++) {
            dts_Receiver.setCellData(i + 1, "CHECK", "T");
        }
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        for (var i = 0; i < dts_Receiver.getTotalRow(); i++) {
            dts_Receiver.setCellData(i + 1, "CHECK", "F");
        }
        btn_SelectedAll.setValue("전체선택");
    }
    grd_Receiver.Redraw = true;
};
scwin.fn_RowCount = function() {
    //alert(dts_Receiver.CountRow);
    $c.stf.setObjectValue(txb_totCnt, "총건수 : " + dts_Receiver.getTotalRow());
};
scwin.isNumber = function(inputVal) {
    oneDecimal = false;
    var inputStr = inputVal.toString();
    var oneChar;
    for (var i = 0; i < inputStr.length; i++) {
        oneChar = inputStr.charAt(i);
        if (i == 0 && oneChar == "-") {
            continue;
        }
        if (oneChar == "." && !oneDecimal) {
            oneDecimal = true;
            continue;
        }
        if (oneChar < "0" || oneChar > "9") {
            return false;
        }
    }
    return true;
};


/**
 * 채권담당자조회(BNS22400)에서 SMS발송 대상자 데이터를 받아온다.
 * - 2022-07-26 by KHJ
 */
scwin.fn_SetDataFromOpener = function() {
    if (frame.opener.dts_Target) {
        grd_Receiver.Redraw = false;
        var nRowCnt = frame.opener.dts_Target.getTotalRow();
        // for문으로 데이터 넣으면 너무 느림.
        dts_Receiver.setJSON(frame.opener.dts_Target.ExportData(1, nRowCnt, false));
        $c.stf.setObjectValue(txb_totCnt, "총건수 : " + dts_Receiver.getTotalRow());
        grd_Receiver.Redraw = true;
    }
};
scwin.img_send_onclick = function() {
    scwin.fn_registerSMS();
};
scwin.img_srch_onclick = async function() {
    var send_url;

    //(유)주식시장운영팀, 코스닥시장운영팀, 코넥스시장운영팀
    //if ( gDepCd == '2220' || gDepCd == '3220'  || gDepCd == '3B10' ) {
    if ($c.stf.getObjectValue(txb_msg_gbn) == '2') {
        send_url = "/bizspt/ULDSTF30320.gfm";
    } else {
        send_url = "/bizspt/ULDSTF30310.gfm";
    }
    await $c.frame.CreateDialogFrame("RECEIVER_FOR_MAIL", send_url, "수신자 선택", 10, 10, 893, 550, "window");
};
scwin.img_cancel_onclick = function() {
    //fn_Cancel();
    scwin.initPage();
};
scwin.trs_Save_OnFail = function() {
    var msg = $c.stf.getMessageParam("MSG-A002", "전송");
    $c.win.alert(msg);
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", "전송");
    $c.win.alert(msg);
    $c.frame.path("../").fn_Search();
    await $c.frame.CloseFrame();
};
scwin.txa_title_OnChange = function() {
    $c.stf.setObjectValue(txb_title_size, $c.stf.getStringSize($c.stf.getObjectValue(txa_title)));
    if ($c.stf.getStringSize($c.stf.getObjectValue(txa_title)) > 80) {
        $c.stf.setObjectValue(txb_alert, '가 초과되었습니다.');
        txa_title.Focus();
        return;
    }
};
scwin.dts_usr_basic_OnLoadError = function() {
    $c.stf.alert_error(dts_usr_basic);
};
scwin.btn_SelectedAll_onclick = function() {
    scwin.fn_SelectAll();
};
scwin.cmb_Reserve_OnSelChange = function() {
    if ($c.stf.getObjectValue(cmb_Reserve) == "Y") {
        $c.stf.showObj(panel_reserve, true);
        $c.stf.setObjectValue(cmb_EMAIL, "N");
        cmb_EMAIL.setDisabled(true);
    } else {
        $c.stf.showObj(panel_reserve, false);
        if ($c.stf.getObjectValue(txb_msg_gbn) == '2') {
            cmb_EMAIL.setDisabled(true);
        } else {
            cmb_EMAIL.setDisabled(false);
        }

        // 예약 전송 날짜 초기값 
        var ToDay = $c.ut.cGetToday2();
        $c.stf.setObjectValue(edt_Reserve_Date, ToDay);

        // 예약 전송 시간 초기값 
        $c.stf.setObjectValue(cmb_Reserve_hh, "99");
        $c.stf.setObjectValue(cmb_Reserve_mm, "99");
        //initPage();

    }
};
scwin.calendar_onclick = function() {
    popUpCalendar2(edt_Reserve_Date);
};
scwin.dts_Receiver_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(txb_totCnt, "총건수 : " + rowcount);
    //CloseWin(rowcount, grd_TrstkSubmit);

};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_HideDebugCtrls();
    scwin.fn_SetHeader();
    scwin.initPage();

    // opener에서 받아온 데이터 세팅
    // 채권담당자조회 화면에서 이 화면을 팝업함. 2022-07-26 by KHJ
    scwin.fn_SetDataFromOpener();
};
